begin;
create table if not exists public.mme_employee_profiles(employee_auth_user_id uuid primary key,employee_number text not null unique,legal_first_name text not null,legal_last_name text not null,preferred_name text,work_email text,work_phone text,hire_date date,employment_type text not null default 'full_time' check(employment_type in('full_time','part_time','contract','temporary','seasonal')),profile_status text not null default 'prehire' check(profile_status in('prehire','active','leave','suspended','terminated')),emergency_contact_name text,emergency_contact_phone text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mme_employee_documents(document_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),document_type text not null check(document_type in('offer_letter','contract','tax_form','identity_verification','policy','certification','performance','disciplinary','other')),document_title text not null,storage_bucket text not null default 'mme-hr-private',storage_path text not null,content_type text,sha256 text,document_status text not null default 'active' check(document_status in('active','superseded','archived','pending_signature')),effective_date date,expiry_date date,uploaded_by_auth_user_id uuid not null,created_at timestamptz not null default now(),unique(storage_bucket,storage_path));
create table if not exists public.mme_hr_onboarding_cases(case_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),case_status text not null default 'not_started' check(case_status in('not_started','in_progress','blocked','completed','cancelled')),start_date date not null,assigned_hr_auth_user_id uuid,manager_auth_user_id uuid,completed_at timestamptz,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_hr_onboarding_tasks(task_id uuid primary key default gen_random_uuid(),case_id uuid not null references public.mme_hr_onboarding_cases(case_id),task_code text not null,task_title text not null,assigned_to_auth_user_id uuid,task_status text not null default 'pending' check(task_status in('pending','in_progress','blocked','completed','waived')),due_date date,completed_at timestamptz,completion_note text,created_at timestamptz not null default now(),unique(case_id,task_code));
create table if not exists public.mme_hr_policy_acknowledgments(acknowledgment_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),policy_code text not null,policy_version text not null,document_id uuid references public.mme_employee_documents(document_id),acknowledgment_status text not null default 'pending' check(acknowledgment_status in('pending','acknowledged','declined','expired')),acknowledged_at timestamptz,attestation_text text,recorded_by_auth_user_id uuid not null,created_at timestamptz not null default now(),unique(employee_auth_user_id,policy_code,policy_version));
create table if not exists public.mme_hr_leave_cases(leave_case_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),leave_type text not null check(leave_type in('pto','sick','family','parental','medical','unpaid','other')),start_date date not null,end_date date not null,leave_status text not null default 'requested' check(leave_status in('requested','approved','denied','cancelled','completed')),reason_private text,decision_note text,reviewed_by_auth_user_id uuid,reviewed_at timestamptz,created_at timestamptz not null default now(),check(end_date>=start_date));
create table if not exists public.mme_hr_offboarding_cases(offboarding_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),separation_date date not null,separation_type text not null check(separation_type in('voluntary','involuntary','contract_end','retirement','other')),case_status text not null default 'in_progress' check(case_status in('in_progress','blocked','completed','cancelled')),access_revocation_confirmed_at timestamptz,payroll_handoff_confirmed_at timestamptz,final_reviewed_by_auth_user_id uuid,completed_at timestamptz,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_hr_offboarding_tasks(task_id uuid primary key default gen_random_uuid(),offboarding_id uuid not null references public.mme_hr_offboarding_cases(offboarding_id),task_code text not null,task_title text not null,task_status text not null default 'pending' check(task_status in('pending','in_progress','blocked','completed','waived')),assigned_to_auth_user_id uuid,completed_at timestamptz,completion_note text,created_at timestamptz not null default now(),unique(offboarding_id,task_code));
create table if not exists public.mme_employee_equipment_assignments(equipment_assignment_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),asset_tag text not null,description text not null,serial_number text,assigned_at timestamptz not null default now(),expected_return_date date,returned_at timestamptz,condition_out text,condition_in text,issued_by_auth_user_id uuid not null,received_by_auth_user_id uuid,unique(employee_auth_user_id,asset_tag,assigned_at));
create table if not exists public.mme_hr_approval_events(approval_event_id uuid primary key default gen_random_uuid(),subject_type text not null check(subject_type in('onboarding','leave','offboarding','document','policy_acknowledgment')),subject_id uuid not null,decision text not null check(decision in('approved','denied','returned','completed')),note text,actor_auth_user_id uuid not null,created_at timestamptz not null default now());
create index if not exists mme_employee_documents_employee_idx on public.mme_employee_documents(employee_auth_user_id,created_at desc);
create index if not exists mme_hr_leave_queue_idx on public.mme_hr_leave_cases(leave_status,start_date);
create index if not exists mme_hr_onboarding_queue_idx on public.mme_hr_onboarding_cases(case_status,start_date);
create index if not exists mme_hr_offboarding_queue_idx on public.mme_hr_offboarding_cases(case_status,separation_date);
do $$declare t text;begin foreach t in array array['mme_employee_profiles','mme_employee_documents','mme_hr_onboarding_cases','mme_hr_onboarding_tasks','mme_hr_policy_acknowledgments','mme_hr_leave_cases','mme_hr_offboarding_cases','mme_hr_offboarding_tasks','mme_employee_equipment_assignments','mme_hr_approval_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
commit;